#define _POSIX_C_SOURCE 200809L
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "mmay/base/hash.h"
#include "mmay/runtime/managed.h"

static uint64_t now(void) {
    struct timespec t;
    if (clock_gettime(CLOCK_MONOTONIC, &t) != 0) return 0;
    return (uint64_t)t.tv_sec * UINT64_C(1000000000) + (uint64_t)t.tv_nsec;
}

int main(int argc, char **argv) {
    static const int64_t pattern[] = {77,97,114,105,109,97,121,32,955,32,26481,20140,32,128640,128578};
    bool is_set = argc > 1 && strcmp(argv[1], "unique-set") == 0;
    bool rune = argc > 1 && strcmp(argv[1], "rune-frequency") == 0;
    bool hash_only = argc > 2 && strcmp(argv[2], "hash") == 0;
    size_t count = rune ? 450000U : 1000000U, length = 0, i;
    MarimayFailAllocator tracked;
    MarimayAllocator allocator;
    MarimayManagedHeap heap;
    MarimayManagedHeapOptions options = mmay_managed_heap_default_options();
    MarimayManagedFieldDescriptor raw = {MMAY_MANAGED_CELL_RAW64, false, MMAY_MANAGED_OBJECT_INVALID, NULL};
    MarimayManagedFieldDescriptor absent = {0};
    MarimayManagedMapDescriptor descriptor = {raw, is_set ? absent : raw, is_set};
    MarimayManagedReference collection = mmay_managed_invalid_reference();
    MarimayManagedCell key = {0}, value = {0};
    int64_t state = is_set ? 19 : 17, checksum = 0;
    int64_t *input;
    uint64_t begin, elapsed, hashes = 0;
    size_t retained;
    bool inserted = false, found = false;
    if (argc < 2) return 1;
    mmay_fail_allocator_init(&tracked, mmay_system_allocator(), SIZE_MAX);
    allocator = mmay_fail_allocator(&tracked);
    input = mmay_allocate(&allocator, count * sizeof(*input));
    if (input == NULL) return 2;
    for (i = 0; i < count; i++) {
        state = (state * 25173 + 13849) % 65536;
        input[i] = rune ? pattern[i % 15U] : is_set ? state % 20001 - 10000 : state % 4096;
    }
    if (!mmay_managed_heap_init(&heap, allocator, options)) return 3;
    begin = now();
    if (hash_only) {
        for (i = 0; i < count; i++) hashes += mmay_hash_sip24_word((uint64_t)input[i],
            options.collection_hash_seed0, options.collection_hash_seed1);
    } else {
        if ((is_set ? mmay_managed_set_new(&heap, &descriptor, &collection)
            : mmay_managed_map_new(&heap, &descriptor, &collection)) != MMAY_MANAGED_OK) return 4;
        for (i = 0; i < count; i++) {
            key.f64_bits = (uint64_t)input[i];
            if (is_set) {
                if (mmay_managed_set_add(&heap, collection, key, &inserted) != MMAY_MANAGED_OK) return 5;
            } else {
                if (mmay_managed_map_get(&heap, collection, key, &value, &found) != MMAY_MANAGED_OK) return 6;
                value.f64_bits = found ? value.f64_bits + 1U : 1U;
                if (mmay_managed_map_put(&heap, collection, key, value, &inserted) != MMAY_MANAGED_OK) return 7;
            }
        }
    }
    elapsed = now() - begin;
    retained = tracked.live_bytes - count * sizeof(*input);
    if (!hash_only) {
        if ((is_set ? mmay_managed_set_length(&heap, collection, &length)
            : mmay_managed_map_length(&heap, collection, &length)) != MMAY_MANAGED_OK) return 8;
        checksum = (int64_t)length;
        if (!is_set) {
            const int64_t selected[] = {0,1,17,4095};
            const size_t runes[] = {0,1,7,8,13,14};
            for (i = 0; i < (rune ? 6U : 4U); i++) {
                key.f64_bits = (uint64_t)(rune ? pattern[runes[i]] : selected[i]);
                if (mmay_managed_map_get(&heap, collection, key, &value, &found) != MMAY_MANAGED_OK || !found) return 9;
                checksum += (int64_t)value.f64_bits;
            }
        }
        if (checksum != (rune ? 270012 : is_set ? 20001 : 5073)) return 10;
    }
    mmay_managed_heap_dispose(&heap);
    mmay_deallocate(&allocator, input, count * sizeof(*input));
    if (tracked.live_allocations != 0 || tracked.live_bytes != 0) return 11;
    printf("{\"ns\":%llu,\"checksum\":%lld,\"hash_sum\":%llu,\"retained_bytes\":%zu}\n",
        (unsigned long long)elapsed, (long long)checksum, (unsigned long long)hashes, retained);
    return 0;
}

